// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Ownable, Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";

/// @title InkWell — 1,000 3D pixel-art ink pens on BNB Smart Chain
/// @notice Configurable ERC-721 with Whitelist, Public and Team mint phases.
///         Prices and per-wallet limits are enforced on-chain and can be changed
///         after deployment by the owner or authorized admins.
/// @dev    Not audited. Test on BSC testnet and get an independent review before mainnet.
contract InkWell is ERC721, ERC2981, Ownable2Step, Pausable, ReentrancyGuard {
    using Strings for uint256;

    // ───────────── Supply ─────────────
    /// @notice Hard cap fixed at deployment. Can NEVER be raised.
    uint256 public immutable MAX_SUPPLY_CAP;
    /// @notice Active max supply. Admin may lower it (never below minted) or raise it back up to MAX_SUPPLY_CAP, unless locked.
    uint256 public maxSupply;
    bool public supplyLocked;
    /// @notice Total ever minted (never decreases, so burning cannot re-open supply).
    uint256 public totalMinted;
    uint256 public totalBurned;

    // ───────────── Roles ─────────────
    mapping(address => bool) public isAdmin;

    // ───────────── Phases ─────────────
    struct Phase {
        bool enabled;       // phase switch (false = closed). All phases start closed.
        uint64 startTime;   // unix seconds, 0 = opens as soon as enabled
        uint64 endTime;     // unix seconds, 0 = no end time
        uint128 price;      // wei per NFT (0 = free, gas still paid by minter)
        uint32 walletLimit; // max NFTs one wallet can mint in this phase (in total, across all its transactions)
        uint32 maxPerTx;    // max NFTs in ONE transaction (0 = no extra per-transaction limit)
    }
    Phase public wlPhase;
    Phase public publicPhase;
    Phase public teamPhase;

    mapping(address => bool) public isWhitelisted;
    mapping(address => bool) public isTeamWallet;
    mapping(address => uint256) public wlMinted;
    mapping(address => uint256) public publicMinted;
    mapping(address => uint256) public teamMinted;

    /// @notice Optional custom WL limit for a specific wallet (0 = use wlPhase.walletLimit).
    mapping(address => uint256) public wlAllowance;

    /// @notice Total NFTs all team wallets together may mint. 0 = team minting blocked.
    uint256 public teamAllocation;
    uint256 public teamMintedTotal;

    /// @notice Optional combined limit for WL + Public per wallet (0 = off, each phase limit applies on its own).
    uint256 public maxPerWalletWLPlusPublic;

    /// @notice Ownership renounce needs to be armed first (two-step safety).
    bool public renounceArmed;

    // ───────────── Metadata ─────────────
    string private _baseTokenURI;
    string public baseExtension = ".json";
    string public unrevealedURI;
    bool public revealed;
    bool public metadataLocked;
    string private _contractURI;

    // ───────────── Funds ─────────────
    address payable public payoutWallet;

    // ───────────── Burning ─────────────
    bool public adminBurnEnabled;               // disabled by default
    bool public adminBurnPermanentlyDisabled;

    // ───────────── Events ─────────────
    event AdminSet(address indexed account, bool allowed);
    event PhaseUpdated(uint8 indexed phase, bool enabled, uint64 startTime, uint64 endTime, uint128 price, uint32 walletLimit, uint32 maxPerTx);
    event WhitelistUpdated(address indexed account, bool allowed);
    event TeamWalletUpdated(address indexed account, bool allowed);
    event Minted(address indexed to, uint8 indexed phase, uint256 firstTokenId, uint256 quantity, uint256 paid);
    event MaxSupplyUpdated(uint256 newMaxSupply);
    event SupplyLocked();
    event BaseURIUpdated(string newBaseURI, string extension);
    event UnrevealedURIUpdated(string uri);
    event Revealed(bool revealed);
    event MetadataLocked();
    event ContractURIUpdated(string uri);
    event PayoutWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event Withdrawn(address indexed to, uint256 amount);
    event AdminBurnSet(bool enabled);
    event AdminBurnPermanentlyDisabled();
    event AdminBurned(address indexed operator, uint256 indexed tokenId);
    event WhitelistAllowanceUpdated(address indexed account, uint256 allowance);
    event TeamAllocationUpdated(uint256 allocation);
    event CombinedWalletLimitUpdated(uint256 limit);
    event RenounceArmed(bool armed);
    event RoyaltyUpdated(address indexed receiver, uint96 feeBps);

    // Phase ids
    uint8 public constant PHASE_WL = 1;
    uint8 public constant PHASE_PUBLIC = 2;
    uint8 public constant PHASE_TEAM = 3;

    // ───────────── Errors ─────────────
    error NotAdmin();
    error ZeroAddress();
    error ZeroQuantity();
    error PhaseClosed();
    error NotEligible();
    error WalletLimitExceeded();
    error SupplyExceeded();
    error WrongPayment(uint256 expected, uint256 sent);
    error Locked();
    error InvalidSupply();
    error AdminBurnDisabled();
    error NothingToWithdraw();
    error TransferFailed();
    error RenounceDisabled();
    error LengthTooLarge();
    error InvalidPhase();
    error InvalidTimes();
    error TxLimitExceeded();
    error TeamAllocationExceeded();
    error RoyaltyTooHigh();
    error LengthMismatch();
    error RenounceNotArmed();

    modifier onlyAdmin() {
        if (msg.sender != owner() && !isAdmin[msg.sender]) revert NotAdmin();
        _;
    }

    constructor(
        address initialOwner,
        address payable initialPayout,
        uint256 supplyCap,
        string memory initialUnrevealedURI
    ) ERC721("InkWell", "INKWELL") Ownable(initialOwner) {
        if (initialPayout == address(0)) revert ZeroAddress();
        if (supplyCap == 0) revert InvalidSupply();
        MAX_SUPPLY_CAP = supplyCap;
        maxSupply = supplyCap;
        payoutWallet = initialPayout;
        unrevealedURI = initialUnrevealedURI;
        // ERC-2981: 2% resale royalty to the payout wallet. Marketplaces may choose not to honor it.
        _setDefaultRoyalty(initialPayout, 200);
        // All phases start CLOSED (price 0, limit 0) and team allocation is 0 — nothing can mint until you configure it.
    }

    // ═════════════ Minting ═════════════

    /// @notice Whitelist mint. Caller must be whitelisted. Send exactly wlPrice * quantity in BNB (wei).
    function mintWhitelist(uint256 quantity) external payable nonReentrant whenNotPaused {
        if (!isWhitelisted[msg.sender]) revert NotEligible();
        _checkPhase(wlPhase, quantity);
        if (wlMinted[msg.sender] + quantity > wlLimitOf(msg.sender)) revert WalletLimitExceeded();
        _checkCombined(msg.sender, quantity);
        wlMinted[msg.sender] += quantity;
        _mintBatch(msg.sender, quantity, wlPhase.price, PHASE_WL);
    }

    /// @notice Public mint. Send exactly publicPrice * quantity in BNB (wei).
    function mintPublic(uint256 quantity) external payable nonReentrant whenNotPaused {
        _checkPhase(publicPhase, quantity);
        if (publicMinted[msg.sender] + quantity > publicPhase.walletLimit) revert WalletLimitExceeded();
        _checkCombined(msg.sender, quantity);
        publicMinted[msg.sender] += quantity;
        _mintBatch(msg.sender, quantity, publicPhase.price, PHASE_PUBLIC);
    }

    /// @notice Team mint. Caller must be an authorized team wallet. Free if teamPrice is 0.
    function mintTeam(uint256 quantity) external payable nonReentrant whenNotPaused {
        if (!isTeamWallet[msg.sender]) revert NotEligible();
        _checkPhase(teamPhase, quantity);
        if (teamMinted[msg.sender] + quantity > teamPhase.walletLimit) revert WalletLimitExceeded();
        if (teamMintedTotal + quantity > teamAllocation) revert TeamAllocationExceeded();
        teamMinted[msg.sender] += quantity;
        teamMintedTotal += quantity;
        _mintBatch(msg.sender, quantity, teamPhase.price, PHASE_TEAM);
    }

    function _checkPhase(Phase memory p, uint256 quantity) private view {
        if (!p.enabled) revert PhaseClosed();
        if (p.startTime != 0 && block.timestamp < p.startTime) revert PhaseClosed();
        if (p.endTime != 0 && block.timestamp > p.endTime) revert PhaseClosed();
        if (p.maxPerTx != 0 && quantity > p.maxPerTx) revert TxLimitExceeded();
    }

    function _checkCombined(address a, uint256 quantity) private view {
        uint256 lim = maxPerWalletWLPlusPublic;
        if (lim != 0 && wlMinted[a] + publicMinted[a] + quantity > lim) revert WalletLimitExceeded();
    }

    /// @notice Effective WL limit for a wallet (custom allowance if set, otherwise the phase limit).
    function wlLimitOf(address a) public view returns (uint256) {
        uint256 custom = wlAllowance[a];
        return custom != 0 ? custom : wlPhase.walletLimit;
    }

    function _mintBatch(address to, uint256 quantity, uint256 price, uint8 phase) private {
        if (quantity == 0) revert ZeroQuantity();
        if (totalMinted + quantity > maxSupply) revert SupplyExceeded();
        uint256 cost = price * quantity;
        if (msg.value != cost) revert WrongPayment(cost, msg.value);

        uint256 first = totalMinted + 1; // token IDs start at 1 (#0001)
        totalMinted += quantity;          // effects before interactions
        for (uint256 i; i < quantity; ++i) {
            _safeMint(to, first + i);
        }
        emit Minted(to, phase, first, quantity, msg.value);
    }

    // ═════════════ Burning ═════════════

    /// @notice Holder (or approved operator) burns their own NFT. Burned IDs are never re-minted.
    function burn(uint256 tokenId) external {
        _update(address(0), tokenId, msg.sender); // reverts unless owner/approved
        totalBurned += 1;
    }

    /// @notice Optional admin burn of any NFT. Disabled by default; owner must enable it.
    function adminBurn(uint256 tokenId) external onlyOwner {
        if (!adminBurnEnabled) revert AdminBurnDisabled();
        _update(address(0), tokenId, address(0));
        totalBurned += 1;
        emit AdminBurned(msg.sender, tokenId);
    }

    function setAdminBurnEnabled(bool enabled) external onlyOwner {
        if (adminBurnPermanentlyDisabled) revert Locked();
        adminBurnEnabled = enabled;
        emit AdminBurnSet(enabled);
    }

    /// @notice One-way switch: admin burn can never be turned on again.
    function permanentlyDisableAdminBurn() external onlyOwner {
        adminBurnEnabled = false;
        adminBurnPermanentlyDisabled = true;
        emit AdminBurnPermanentlyDisabled();
    }

    // ═════════════ Admin: phases & lists ═════════════

    /// @notice Set every setting of one phase at once (1 = WL, 2 = Public, 3 = Team).
    function setPhase(
        uint8 phase, bool enabled, uint64 startTime, uint64 endTime,
        uint128 price, uint32 walletLimit, uint32 maxPerTx
    ) external onlyAdmin {
        if (endTime != 0 && endTime <= startTime) revert InvalidTimes();
        Phase storage p = _phase(phase);
        p.enabled = enabled; p.startTime = startTime; p.endTime = endTime;
        p.price = price; p.walletLimit = walletLimit; p.maxPerTx = maxPerTx;
        _emitPhase(phase);
    }

    /// @notice Open (true) or pause (false) a single phase without touching the others.
    function setPhaseEnabled(uint8 phase, bool enabled) external onlyAdmin {
        _phase(phase).enabled = enabled;
        _emitPhase(phase);
    }

    function setPhasePrice(uint8 phase, uint128 price) external onlyAdmin {
        _phase(phase).price = price;
        _emitPhase(phase);
    }

    function setPhaseWalletLimit(uint8 phase, uint32 walletLimit) external onlyAdmin {
        _phase(phase).walletLimit = walletLimit;
        _emitPhase(phase);
    }

    function setPhaseMaxPerTx(uint8 phase, uint32 maxPerTx) external onlyAdmin {
        _phase(phase).maxPerTx = maxPerTx;
        _emitPhase(phase);
    }

    function setPhaseTimes(uint8 phase, uint64 startTime, uint64 endTime) external onlyAdmin {
        if (endTime != 0 && endTime <= startTime) revert InvalidTimes();
        Phase storage p = _phase(phase);
        p.startTime = startTime; p.endTime = endTime;
        _emitPhase(phase);
    }

    function _emitPhase(uint8 phase) private {
        Phase storage p = _phase(phase);
        emit PhaseUpdated(phase, p.enabled, p.startTime, p.endTime, p.price, p.walletLimit, p.maxPerTx);
    }

    function _phase(uint8 phase) private view returns (Phase storage) {
        if (phase == PHASE_WL) return wlPhase;
        if (phase == PHASE_PUBLIC) return publicPhase;
        if (phase == PHASE_TEAM) return teamPhase;
        revert InvalidPhase();
    }

    /// @notice Optional combined WL + Public limit per wallet (0 = off).
    function setCombinedWalletLimit(uint256 limit) external onlyAdmin {
        maxPerWalletWLPlusPublic = limit;
        emit CombinedWalletLimitUpdated(limit);
    }

    /// @notice Give specific WL wallets their own limit (also whitelists them). Allowance 0 = use the default WL limit.
    function setWhitelistAllowances(address[] calldata accounts, uint256[] calldata allowances) external onlyAdmin {
        if (accounts.length != allowances.length) revert LengthMismatch();
        if (accounts.length > 500) revert LengthTooLarge();
        for (uint256 i; i < accounts.length; ++i) {
            if (accounts[i] == address(0)) revert ZeroAddress();
            isWhitelisted[accounts[i]] = true;
            wlAllowance[accounts[i]] = allowances[i];
            emit WhitelistUpdated(accounts[i], true);
            emit WhitelistAllowanceUpdated(accounts[i], allowances[i]);
        }
    }

    /// @notice Total NFTs the whole team may mint. Cannot be set below what the team already minted.
    function setTeamAllocation(uint256 allocation) external onlyOwner {
        if (allocation < teamMintedTotal || allocation > MAX_SUPPLY_CAP) revert InvalidSupply();
        teamAllocation = allocation;
        emit TeamAllocationUpdated(allocation);
    }

    function setWhitelist(address[] calldata accounts, bool allowed) external onlyAdmin {
        if (accounts.length > 500) revert LengthTooLarge();
        for (uint256 i; i < accounts.length; ++i) {
            if (accounts[i] == address(0)) revert ZeroAddress();
            isWhitelisted[accounts[i]] = allowed;
            if (!allowed && wlAllowance[accounts[i]] != 0) { wlAllowance[accounts[i]] = 0; emit WhitelistAllowanceUpdated(accounts[i], 0); }
            emit WhitelistUpdated(accounts[i], allowed);
        }
    }

    function setTeamWallets(address[] calldata accounts, bool allowed) external onlyAdmin {
        if (accounts.length > 100) revert LengthTooLarge();
        for (uint256 i; i < accounts.length; ++i) {
            if (accounts[i] == address(0)) revert ZeroAddress();
            isTeamWallet[accounts[i]] = allowed;
            emit TeamWalletUpdated(accounts[i], allowed);
        }
    }

    function pause() external onlyAdmin { _pause(); }
    function unpause() external onlyAdmin { _unpause(); }

    // ═════════════ Admin: supply ═════════════

    /// @notice Set active max supply between totalMinted and MAX_SUPPLY_CAP. Never above the deploy-time cap.
    function setMaxSupply(uint256 newMax) external onlyOwner {
        if (supplyLocked) revert Locked();
        if (newMax < totalMinted || newMax > MAX_SUPPLY_CAP) revert InvalidSupply();
        maxSupply = newMax;
        emit MaxSupplyUpdated(newMax);
    }

    function lockSupply() external onlyOwner {
        supplyLocked = true;
        emit SupplyLocked();
    }

    // ═════════════ Admin: metadata ═════════════

    function setBaseURI(string calldata newBaseURI, string calldata extension) external onlyAdmin {
        if (metadataLocked) revert Locked();
        _baseTokenURI = newBaseURI;
        baseExtension = extension;
        emit BaseURIUpdated(newBaseURI, extension);
    }

    function setUnrevealedURI(string calldata uri) external onlyAdmin {
        if (metadataLocked) revert Locked();
        unrevealedURI = uri;
        emit UnrevealedURIUpdated(uri);
    }

    function setRevealed(bool value) external onlyAdmin {
        if (metadataLocked) revert Locked();
        revealed = value;
        emit Revealed(value);
    }

    function setContractURI(string calldata uri) external onlyAdmin {
        _contractURI = uri;
        emit ContractURIUpdated(uri);
    }

    /// @notice One-way: freezes baseURI, extension, unrevealedURI and revealed flag forever.
    function lockMetadata() external onlyOwner {
        metadataLocked = true;
        emit MetadataLocked();
    }

    // ═════════════ Owner: funds & roles ═════════════

    function setAdmin(address account, bool allowed) external onlyOwner {
        if (account == address(0)) revert ZeroAddress();
        isAdmin[account] = allowed;
        emit AdminSet(account, allowed);
    }

    function setPayoutWallet(address payable newWallet) external onlyOwner {
        if (newWallet == address(0)) revert ZeroAddress();
        emit PayoutWalletUpdated(payoutWallet, newWallet);
        payoutWallet = newWallet;
    }

    // ═════════════ Royalties (ERC-2981) ═════════════
    uint96 public constant MAX_ROYALTY_BPS = 1000; // 10% ceiling, forever

    /// @notice Resale royalty in basis points (200 = 2%) and who receives it. Owner only.
    function setRoyalty(address receiver, uint96 feeBps) external onlyOwner {
        if (receiver == address(0)) revert ZeroAddress();
        if (feeBps > MAX_ROYALTY_BPS) revert RoyaltyTooHigh();
        _setDefaultRoyalty(receiver, feeBps);
        emit RoyaltyUpdated(receiver, feeBps);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    /// @notice Sends the full contract balance to payoutWallet only. Callable by owner or admin.
    function withdraw() external onlyAdmin nonReentrant {
        uint256 amount = address(this).balance;
        if (amount == 0) revert NothingToWithdraw();
        address payable to = payoutWallet;
        emit Withdrawn(to, amount);
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    /// @notice Step 1 of renouncing. Arm (true) or disarm (false).
    function armRenounce(bool armed) external onlyOwner {
        renounceArmed = armed;
        emit RenounceArmed(armed);
    }

    /// @notice IRREVERSIBLE. Step 2: removes the owner forever. Nobody can change owner-only settings,
    ///         withdraw through the owner, or add admins again. Must be armed first.
    function renounceOwnership() public override onlyOwner {
        if (!renounceArmed) revert RenounceNotArmed();
        renounceArmed = false;
        super.renounceOwnership();
    }

    // ═════════════ Views ═════════════

    function totalSupply() external view returns (uint256) { return totalMinted - totalBurned; }
    function remainingSupply() external view returns (uint256) { return maxSupply - totalMinted; }

    function contractURI() external view returns (string memory) { return _contractURI; }
    function baseURI() external view returns (string memory) { return _baseTokenURI; }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        _requireOwned(tokenId);
        if (!revealed || bytes(_baseTokenURI).length == 0) return unrevealedURI;
        return string.concat(_baseTokenURI, tokenId.toString(), baseExtension);
    }

    struct MintInfo {
        bool paused;
        Phase wl;
        Phase pub;
        Phase team;
        uint256 maxSupply;
        uint256 totalMinted;
        uint256 totalBurned;
        uint256 remaining;
        address payoutWallet;
        uint256 teamAllocation;
        uint256 teamMintedTotal;
        uint256 maxPerWalletWLPlusPublic;
        bool revealed;
        uint256 balance;
    }

    /// @notice One call for the website: every mint setting and supply figure.
    function getMintInfo() external view returns (MintInfo memory) {
        return MintInfo(
            paused(), wlPhase, publicPhase, teamPhase, maxSupply, totalMinted, totalBurned,
            maxSupply - totalMinted, payoutWallet, teamAllocation, teamMintedTotal,
            maxPerWalletWLPlusPublic, revealed, address(this).balance
        );
    }

    /// @notice Per-wallet status for the WL checker / AI agents.
    function getWalletInfo(address account) external view returns (
        bool whitelisted, bool team, uint256 wlCount, uint256 publicCount, uint256 teamCount, uint256 balance, uint256 wlLimit
    ) {
        return (isWhitelisted[account], isTeamWallet[account], wlMinted[account], publicMinted[account], teamMinted[account], balanceOf(account), wlLimitOf(account));
    }

    // Reject stray BNB not sent through a mint function.
    receive() external payable { revert(); }
}
